
(function(){
  'use strict';
  const home=document.getElementById('scHome');if(!home||!window.WORDTIDE_MEMORY)return;
  const art={"tide-light":"data:image/webp;base64,","tide-dark":"data:image/webp;base64,","explore-light":"data:image/webp;base64,","explore-dark":"data:image/webp;base64,","boss-light":"data:image/webp;base64,","boss-dark":"data:image/webp;base64,","wordtide-wave":"data:image/webp;base64,"};
  const paths={home:'M3 10 12 3 21 10v11h-6v-7H9v7H3Z',book:'M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-1-7-2-10 1Zm0 0v16',chat:'M4 3h16v14H9l-5 4V3Zm4 5h8M8 12h6',compass:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20ZM8 16l2-6 6-2-2 6-6 2Z',crown:'m2 6 5 4 5-7 5 7 5-4-3 14H5L2 6Z',stats:'M5 20V10m7 10V4m7 16V8',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-3c0-7 16-7 16 0v3',sound:'M3 9h4l5-5v16l-5-5H3V9Zm13-2c4 3 4 7 0 10m3-13c6 5 6 11 0 16',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',leaf:'M12 21V10M12 14C3 15 2 8 2 3c8 0 11 5 10 11Zm0 1C12 6 17 4 22 4c0 7-3 11-10 11Z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z'};
  const icon=n=>'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="'+paths[n]+'"/></svg>';
  const root=document.createElement('div');root.id='oceanHome';
  root.innerHTML=`<header class="ox-header"><div class="ox-brand"><span class="ox-logo"><img src="${art['wordtide-wave']}" alt=""></span><div><b>词潮 <span>WordTide</span></b><small>让每一个词，激起思考的潮汐</small></div></div><div class="ox-head-actions"><span class="ox-wallet" title="潮汐币"><span aria-hidden="true">◉</span> <b id="oxCoin">0</b></span><button id="oxAppearance" class="ox-icon-button" aria-label="切换深色模式"></button></div></header>
  <main id="oxDashboard"><section class="ox-tide"><div class="ox-tide-copy"><h1>今日潮汐</h1><p class="ox-due"><strong id="oxDue">0</strong> 个到期词</p><p id="oxEstimate">准备今日计划</p></div><button class="ox-round" data-action="daily" aria-label="查看今日学习计划">›</button><div class="ox-progress-area"><div class="ox-progress-track" role="progressbar" aria-label="当前一轮学习进度" aria-valuemin="0" aria-valuemax="100" id="oxProgress"><i></i></div><div class="ox-progress-meta"><span id="oxPlanNote">一点积累，一点进步</span><span><b id="oxProgressText">0 / 0</b> <span id="oxProgressLabel">本轮进度</span></span></div></div><button class="ox-primary" id="oxContinue">开始今日学习 <span>→</span></button></section>
  <div class="ox-main-grid"><button class="ox-mode" data-action="word"><span class="ox-feature-icon">${icon('book')}</span><span class="ox-small-arrow">›</span><h2>背单词</h2><p>从词汇出发<br>认识、组装到默写</p></button><button class="ox-mode" data-action="sentence"><span class="ox-feature-icon">${icon('chat')}</span><span class="ox-small-arrow">›</span><h2>练句子</h2><p>在真实语境中<br>巩固词汇与表达</p></button></div>
  <div class="ox-section-title"><h2>探索更多</h2><button data-action="theme">查看海域 ›</button></div><div class="ox-explore-grid"><button class="ox-explore ox-island" data-action="theme"><span class="ox-mini-icon">${icon('compass')}</span><h2>主题海域</h2><p>从生活场景出发<br>系统学习</p></button><button class="ox-explore ox-boss" data-action="boss"><span class="ox-mini-icon">${icon('crown')}</span><h2>Boss 挑战</h2><p>挑战海域关卡<br>检验学习成果</p></button></div>
  <div class="ox-section-title"><h2>更多功能</h2></div><div class="ox-shortcuts"><button data-action="farm">${icon('leaf')}<span>潮汐农场</span></button><button data-action="import">${icon('upload')}<span>导入生词</span></button><button data-action="audio">${icon('sound')}<span>声音设置</span></button></div></main>
  <section id="oxStats" class="ox-secondary" hidden><h1>学习统计</h1><p>主题海域 · 与每日计划使用同一份进度</p><div class="ox-stat-grid" id="oxStatsGrid"></div><button class="ox-primary" data-action="daily">安排下一轮学习 →</button><button class="ox-secondary-button" data-action="legacy">查看词库进度与设置</button></section>
  <section id="oxSettings" class="ox-secondary" hidden><h1>我的词潮</h1><p>进度保存在当前浏览器，建议定期导出备份。</p><div class="ox-settings-grid"><button data-action="audio">声音与背景音乐 ›</button><button data-action="appearance">切换浅色 / 深色 ›</button><button data-action="export">导出存档 ›</button><button data-action="restore">导入存档 ›</button><button data-action="legacy">词库、速度与更多设置 ›</button></div></section>
  <div id="oxLegacyHeading" class="ox-secondary" hidden><h1>词库与更多设置</h1><button class="ox-secondary-button" data-action="settings">← 返回我的词潮</button></div>
  <nav class="ox-nav" aria-label="主导航">${[['home','home','首页'],['book','daily','学习'],['compass','theme','海域'],['stats','stats','统计'],['user','settings','我的']].map(([i,a,t])=>`<button data-action="${a}" data-nav="${a}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;
  home.insertBefore(root,home.firstChild);home.classList.add('ox-ready');
  for(const name of ['tide-light','tide-dark','explore-light','explore-dark','boss-light','boss-dark'])root.style.setProperty('--'+name,'url("'+art[name]+'")');
  let view='home';
  function appearance(){const dark=S.themeAppearance==='dark';root.dataset.appearance=dark?'dark':'light';home.dataset.appearance=root.dataset.appearance;const b=document.getElementById('oxAppearance');b.innerHTML=icon(dark?'sun':'moon');b.setAttribute('aria-label',dark?'切换浅色模式':'切换深色模式');b.setAttribute('aria-pressed',String(dark));}
  if(!['light','dark'].includes(S.themeAppearance))S.themeAppearance=window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light';
  function toggle(){S.themeAppearance=S.themeAppearance==='dark'?'light':'dark';appearance();save()}
  function currentSession(){const x=S.dailySession;return x&&Array.isArray(x.queue)&&!x.completed&&x.index<x.queue.length?x:null}
  function update(){
    const s=WORDTIDE_MEMORY.stats(),session=currentSession(),plan=session||WORDTIDE_MEMORY.buildDailyQueue('quick'),length=plan.queue.length,index=session?Math.max(0,Math.min(length,session.index|0)):0,percent=length?Math.round(index/length*100):0;
    document.getElementById('oxDue').textContent=s.due;document.getElementById('oxCoin').textContent=(S.farm?.coin||0).toLocaleString();
    document.getElementById('oxEstimate').textContent='预计 '+(plan.estimateMinutes||1)+' 分钟'+(session?' · 可继续上次学习':' · 新旧词搭配');
    document.getElementById('oxPlanNote').textContent=session?'接着上次，继续前进':s.due?'温习旧词，也认识新词':'没有到期词，学一点新的';
    document.getElementById('oxProgressText').textContent=index+' / '+length;document.getElementById('oxProgressLabel').textContent=session?'本轮进度':'待开始';
    const p=document.getElementById('oxProgress');p.setAttribute('aria-valuenow',String(percent));p.querySelector('i').style.width=percent+'%';
    document.getElementById('oxContinue').innerHTML=(session?'继续今日学习':'开始今日学习')+' <span>→</span>';
    document.getElementById('oxStatsGrid').innerHTML=[['到期复习',s.due],['正在学习',s.learning],['已稳定掌握',s.stable],['尚未开始',s.fresh],['薄弱词',s.weak],['主题总词数',s.total]].map(([t,n])=>'<div><span>'+t+'</span><strong>'+n+'</strong></div>').join('');
  }
  function showView(next){view=next;document.getElementById('oxDashboard').hidden=next!=='home';document.getElementById('oxStats').hidden=next!=='stats';document.getElementById('oxSettings').hidden=next!=='settings';document.getElementById('oxLegacyHeading').hidden=next!=='legacy';home.classList.toggle('ox-legacy',next==='legacy');root.querySelectorAll('[data-nav]').forEach(b=>{const active=b.dataset.nav===(next==='legacy'?'settings':next);b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});home.scrollTop=0;update()}
  const click=id=>document.getElementById(id)?.click();
  function action(a){if(['home','stats','settings','legacy'].includes(a)){showView(a);return}
    if(a==='daily')WORDTIDE_MEMORY.openDaily();else if(a==='word')WORDTIDE_THEME.open();else if(a==='theme')click('btnThemeHome');else if(a==='sentence')click('btnSent2');else if(a==='boss')click('btnBossHome');else if(a==='farm')click('btnFarm3');else if(a==='import')click('btnImport3');else if(a==='audio')click('wtAudioButton');else if(a==='export')click('btnExport');else if(a==='restore')click('btnImportSave');else if(a==='appearance')toggle();
  }
  root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
  document.getElementById('oxAppearance').onclick=toggle;
  document.getElementById('oxContinue').onclick=()=>{if(!WORDTIDE_MEMORY.resumeSession())WORDTIDE_MEMORY.openDaily()};
  const oldShow=window.showScreen;window.showScreen=function(id){const r=oldShow.apply(this,arguments);document.body.classList.toggle('ox-home-visible',id==='scHome');if(id==='scHome'){showView('home');appearance()}return r};
  window.addEventListener('wordtide-memory-updated',()=>{if(document.querySelector('#scHome.on'))update()});
  window.OCEAN_HOME={update,showView,action,toggle,view:()=>view};
  document.body.classList.toggle('ox-home-visible',home.classList.contains('on'));appearance();showView('home');
})();

